export const ViewDefinitionStatusKeyToLabel = {
  'Active': 'Active',
  'Inactive': 'Inactive'
} as const;
export type ViewDefinitionStatusKey = keyof typeof ViewDefinitionStatusKeyToLabel;

export const ViewDefinitionSurfaceKeyToLabel = {
  'Requester': 'Requester',
  'Agent': 'Agent'
} as const;
export type ViewDefinitionSurfaceKey = keyof typeof ViewDefinitionSurfaceKeyToLabel;

export interface ViewDefinition {
  /**
   * @displayName View Definition ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName View Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  viewName: string;
  /**
   * @displayName Entity Name
   * @validationRule Required for create/update operations
   */
  entityName: string;
  /**
   * @displayName Status
   * @validationRule Required for create/update operations
   */
  statusKey: ViewDefinitionStatusKey;
  /**
   * @displayName Surface
   * @validationRule Required for create/update operations
   */
  surfaceKey: ViewDefinitionSurfaceKey;
  /**
   * @displayName Version
   * @validationRule Required for create/update operations
   */
  version: number;
  /**
   * @displayName View Key
   * @validationRule Required for create/update operations
   */
  viewKey: string;
}

export const _ViewDefinition = 'ViewDefinition' as const;